<style>
.feature-heading{display:flex;gap:24px;align-items:center;justify-content:space-between;margin-bottom:24px}.feature-heading h1{font-size:32px;margin:0 0 8px}.muted{color:var(--muted)}
.feature-panel{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:24px;margin:24px 0}.feature-stack{display:grid;gap:16px}.feature-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px}.feature-two{display:grid;grid-template-columns:1fr 1fr;gap:24px}.feature-actions{display:flex;align-items:center;gap:16px;flex-wrap:wrap}.feature-choice{display:flex;gap:8px;align-items:center;padding:8px}.feature-choice input{width:auto}.feature-choices{display:flex;flex-wrap:wrap;gap:8px}
.movie-card{display:block;text-decoration:none;background:var(--surface);border:1px solid var(--border);border-radius:8px;overflow:hidden}.movie-poster,.poster-placeholder{display:block;width:100%;aspect-ratio:2/3;object-fit:cover;background:#202832}.poster-placeholder{display:grid;place-items:center;color:var(--muted)}.movie-card-info{padding:16px}.movie-card-info h3{font-size:16px;margin:0 0 8px}.movie-card-info p{font-size:14px;color:var(--muted);margin:0}.feature-empty{padding:32px;border:1px dashed var(--border);border-radius:8px}.feature-table{overflow-x:auto}.feature-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.feature-stat{padding:24px;border:1px solid var(--border);background:var(--surface);border-radius:8px}.feature-stat strong{display:block;font-size:32px}.feature-pager{display:flex;gap:24px;margin-top:24px}.feature-tag{font-size:12px;color:var(--accent)}.feature-nav{display:flex;gap:24px;flex-wrap:wrap;margin-bottom:24px}.feature-panel label{display:block}.feature-panel fieldset{border:1px solid var(--border);padding:16px}
@media(max-width:700px){.feature-grid,.feature-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.feature-two{grid-template-columns:1fr}.feature-heading{align-items:start;flex-direction:column}.feature-grid{gap:16px}}
</style>
